#!/usr/bin/env python3
"""
Unified API Interface for Transcriptional Regulation Databases
Integrates: JASPAR, ENCODE, UCSC, Cistrome
"""

import sys
import os
import json
import argparse
from pathlib import Path

# Add parent directory to path to import individual APIs
sys.path.insert(0, str(Path(__file__).parent.parent))

class UnifiedTranscriptionalAPI:
    """Unified interface for transcriptional regulation databases"""

    def __init__(self, cache_dir=None):
        self.cache_dir = cache_dir or Path.home() / ".cache" / "unified_api"
        self.cache_dir.mkdir(parents=True, exist_ok=True)

        # Initialize individual API clients
        self.apis = {}
        self._initialize_apis()

    def _initialize_apis(self):
        """Initialize all individual API clients"""
        try:
            # Import JASPAR API
            sys.path.insert(0, '/data/auto_installed_tools/online_databases/jaspar_api/script')
            from jaspar_api import JASPARClient
            self.apis['jaspar'] = JASPARClient(cache_dir=self.cache_dir / 'jaspar')
        except ImportError:
            print("Warning: JASPAR API not available")

        try:
            # Import ENCODE API
            sys.path.insert(0, '/data/auto_installed_tools/online_databases/encode_api/script')
            from encode_api import ENCODEClient
            self.apis['encode'] = ENCODEClient(cache_dir=self.cache_dir / 'encode')
        except ImportError:
            print("Warning: ENCODE API not available")

        try:
            # Import UCSC API
            sys.path.insert(0, '/data/auto_installed_tools/online_databases/ucsc_api/script')
            from ucsc_api import UCSCClient
            self.apis['ucsc'] = UCSCClient(cache_dir=self.cache_dir / 'ucsc')
        except ImportError:
            print("Warning: UCSC API not available")

        try:
            # Import Cistrome API
            sys.path.insert(0, '/data/auto_installed_tools/online_databases/cistrome_api/script')
            from cistrome_api import CistromeClient
            self.apis['cistrome'] = CistromeClient(cache_dir=self.cache_dir / 'cistrome')
        except ImportError:
            print("Warning: Cistrome API not available")

    def search(self, query, databases=None, limit=10):
        """
        Unified search across all databases

        Args:
            query: Search term (TF name, gene, region, etc.)
            databases: List of databases to search (default: all)
            limit: Maximum results per database

        Returns:
            Dictionary with results from each database
        """
        if databases is None:
            databases = list(self.apis.keys())

        results = {}

        for db in databases:
            if db not in self.apis:
                results[db] = {"error": f"Database {db} not available"}
                continue

            try:
                if db == 'jaspar':
                    # Search for TF motifs
                    results[db] = self.apis[db].search_matrices(
                        name=query, 
                        species='human',
                        limit=limit
                    )
                elif db == 'encode':
                    # Search for experiments
                    results[db] = self.apis[db].search_experiments(
                        search_term=query,
                        limit=limit
                    )
                elif db == 'ucsc':
                    # Search genome
                    results[db] = self.apis[db].search_genome(
                        query=query,
                        limit=limit
                    )
                elif db == 'cistrome':
                    # Search datasets
                    results[db] = self.apis[db].search_datasets(
                        keyword=query,
                        limit=limit
                    )
            except Exception as e:
                results[db] = {"error": str(e)}

        return results

    def get_tf_data(self, tf_name, species='human'):
        """
        Get comprehensive TF data from all databases

        Args:
            tf_name: Transcription factor name
            species: Species (human, mouse, etc.)

        Returns:
            Integrated TF data
        """
        tf_data = {
            'tf_name': tf_name,
            'species': species,
            'sources': {}
        }

        # Get motifs from JASPAR
        if 'jaspar' in self.apis:
            try:
                motifs = self.apis['jaspar'].search_matrices(
                    name=tf_name,
                    species=species,
                    limit=5
                )
                tf_data['sources']['jaspar'] = motifs
            except Exception as e:
                tf_data['sources']['jaspar'] = {"error": str(e)}

        # Get ChIP-seq data from ENCODE
        if 'encode' in self.apis:
            try:
                encode_data = self.apis['encode'].search_experiments(
                    target=tf_name,
                    assay_title='ChIP-seq',
                    limit=5
                )
                tf_data['sources']['encode'] = encode_data
            except Exception as e:
                tf_data['sources']['encode'] = {"error": str(e)}

        # Get datasets from Cistrome
        if 'cistrome' in self.apis:
            try:
                cistrome_data = self.apis['cistrome'].search_datasets(
                    factor=tf_name,
                    species=species,
                    limit=5
                )
                tf_data['sources']['cistrome'] = cistrome_data
            except Exception as e:
                tf_data['sources']['cistrome'] = {"error": str(e)}

        # Get gene info from UCSC
        if 'ucsc' in self.apis:
            try:
                # Assuming TF name is a gene symbol
                ucsc_data = self.apis['ucsc'].search_genome(
                    query=tf_name,
                    limit=5
                )
                tf_data['sources']['ucsc'] = ucsc_data
            except Exception as e:
                tf_data['sources']['ucsc'] = {"error": str(e)}

        return tf_data

    def get_genomic_region_data(self, chrom, start, end, genome='hg38'):
        """
        Get comprehensive data for a genomic region

        Args:
            chrom: Chromosome
            start: Start position
            end: End position
            genome: Genome assembly

        Returns:
            Integrated region data
        """
        region_data = {
            'region': f"{chrom}:{start}-{end}",
            'genome': genome,
            'sources': {}
        }

        # Get sequence from UCSC
        if 'ucsc' in self.apis:
            try:
                sequence = self.apis['ucsc'].get_sequence(
                    genome=genome,
                    chrom=chrom,
                    start=start,
                    end=end
                )
                region_data['sources']['ucsc_sequence'] = sequence
            except Exception as e:
                region_data['sources']['ucsc_sequence'] = {"error": str(e)}

        # Get track data from UCSC
        if 'ucsc' in self.apis:
            try:
                tracks = self.apis['ucsc'].get_track_data(
                    genome=genome,
                    track='knownGene',
                    chrom=chrom,
                    start=start,
                    end=end
                )
                region_data['sources']['ucsc_tracks'] = tracks
            except Exception as e:
                region_data['sources']['ucsc_tracks'] = {"error": str(e)}

        # Search for ChIP-seq peaks in this region from ENCODE
        if 'encode' in self.apis:
            try:
                # This would require more complex filtering
                region_data['sources']['encode'] = "Region-specific search not implemented"
            except Exception as e:
                region_data['sources']['encode'] = {"error": str(e)}

        return region_data

    def export_results(self, results, format='json', output_file=None):
        """
        Export results in specified format

        Args:
            results: Results dictionary
            format: Output format (json, csv, bed)
            output_file: Output file path (if None, print to stdout)
        """
        if format == 'json':
            output = json.dumps(results, indent=2)
        elif format == 'csv':
            # Simple CSV conversion
            import csv
            import io

            output = io.StringIO()
            writer = csv.writer(output)

            # Flatten results for CSV
            for db, data in results.items():
                writer.writerow([db, str(data)])

            output = output.getvalue()
        else:
            output = str(results)

        if output_file:
            with open(output_file, 'w') as f:
                f.write(output)
            print(f"Results written to {output_file}")
        else:
            print(output)

        return output

def main():
    parser = argparse.ArgumentParser(description='Unified API for Transcriptional Regulation Databases')
    parser.add_argument('command', choices=['search', 'tf', 'region', 'list'], 
                       help='Command to execute')
    parser.add_argument('--query', help='Search query or TF name')
    parser.add_argument('--chrom', help='Chromosome for region query')
    parser.add_argument('--start', type=int, help='Start position for region query')
    parser.add_argument('--end', type=int, help='End position for region query')
    parser.add_argument('--genome', default='hg38', help='Genome assembly')
    parser.add_argument('--species', default='human', help='Species')
    parser.add_argument('--databases', help='Comma-separated list of databases')
    parser.add_argument('--limit', type=int, default=10, help='Result limit')
    parser.add_argument('--format', choices=['json', 'csv', 'text'], default='json',
                       help='Output format')
    parser.add_argument('--output', help='Output file')

    args = parser.parse_args()

    # Initialize unified API
    api = UnifiedTranscriptionalAPI()

    # Execute command
    if args.command == 'search':
        if not args.query:
            print("Error: --query is required for search command")
            sys.exit(1)

        databases = args.databases.split(',') if args.databases else None
        results = api.search(args.query, databases, args.limit)
        api.export_results(results, args.format, args.output)

    elif args.command == 'tf':
        if not args.query:
            print("Error: --query is required for tf command (TF name)")
            sys.exit(1)

        tf_data = api.get_tf_data(args.query, args.species)
        api.export_results(tf_data, args.format, args.output)

    elif args.command == 'region':
        if not all([args.chrom, args.start, args.end]):
            print("Error: --chrom, --start, and --end are required for region command")
            sys.exit(1)

        region_data = api.get_genomic_region_data(
            args.chrom, args.start, args.end, args.genome
        )
        api.export_results(region_data, args.format, args.output)

    elif args.command == 'list':
        print("Available databases:", list(api.apis.keys()))

if __name__ == '__main__':
    main()
